  background: var(--danger-strong);
  border-color: var(--danger-strong);
}

.icon {
  width: 16px; height: 16px;
  flex-shrink: 0;
}

/* Toast */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  background: #1c2230;
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 10px 16px;
  border-radius: 999px;
  font-size: 14px;
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: 10px;
  z-index: 60;
}
.toast .dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--danger-strong);
  box-shadow: 0 0 0 3px rgba(239, 79, 94, 0.18);
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 6, 10, 0.66);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 50;
  animation: fade 140ms ease-out;
}
.modal {
  width: min(440px, 100%);
  background: linear-gradient(180deg, #161a23 0%, #11141b 100%);
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  box-shadow: var(--shadow-lg);
  padding: 22px 22px 18px;
  animation: pop 160ms cubic-bezier(.2,.9,.3,1.2);
  outline: none;
}
.modal-head {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 14px;
}
.modal-icon {
  flex-shrink: 0;
  width: 40px; height: 40px;
  border-radius: 10px;
  background: var(--danger-bg);
  border: 1px solid #5a1f27;
  color: var(--danger-strong);
  display: grid; place-items: center;
}
.modal h2 {
  margin: 0 0 4px;
  font-size: 17px;
  letter-spacing: 0.1px;
}
.modal p { margin: 0; color: var(--text-muted); font-size: 14px; }
.modal-thumb {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px;
  margin: 14px 0 18px;
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
  border-radius: 10px;
}
.modal-thumb img {
  width: 56px; height: 56px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
}
.modal-thumb .meta { display: grid; gap: 2px; min-width: 0; }
.modal-thumb .name {
  font-size: 14px; font-weight: 600;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.modal-thumb .info { color: var(--text-dim); font-size: 12px; }
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop {
