  color: #0b0d12;
  padding: 8px 14px;
  border-radius: 0 0 8px 0;
  font-weight: 600;
  z-index: 100;
}
.skip-link:focus { left: 0; outline: 3px solid var(--focus); }

.app {
  max-width: 980px;
  margin: 0 auto;
  padding: 32px 24px 64px;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 32px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 600;
  letter-spacing: 0.2px;
}
.brand-mark {
  width: 30px; height: 30px;
  border-radius: 8px;
  background: linear-gradient(135deg, #6c8bff, #b58bff);
  display: grid; place-items: center;
  color: #0b0d12;
  font-weight: 800;
}
.crumbs {
  color: var(--text-dim);
  font-size: 14px;
}
.crumbs a { color: var(--text-muted); text-decoration: none; }
.crumbs a:hover { color: var(--text); }
.crumbs [aria-current="page"] { color: var(--text); }

.preview {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}
@media (min-width: 760px) {
  .preview { grid-template-columns: 1.4fr 1fr; align-items: start; }
}

.preview-figure {
  margin: 0;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
}
.preview-figure img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}
.preview-figure figcaption {
  padding: 14px 18px;
  color: var(--text-muted);
  font-size: 14px;
  border-top: 1px solid var(--border);
}

.meta-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
}
.meta-card h1 {
  margin: 0 0 6px;
  font-size: 22px;
  letter-spacing: 0.2px;
}
.meta-card .sub {
  color: var(--text-muted);
  font-size: 14px;
  margin-bottom: 18px;
}
.meta-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 8px 16px;
  font-size: 14px;
  margin-bottom: 22px;
}
.meta-grid dt { color: var(--text-dim); }
.meta-grid dd { margin: 0; color: var(--text); }

.actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  appearance: none;
  border: 1px solid var(--border-strong);
  background: var(--bg-elev-2);
  color: var(--text);
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 120ms ease, border-color 120ms ease, transform 120ms ease;
}
.btn:hover { background: #1c2230; border-color: #3a4358; }
.btn:active { transform: translateY(1px); }
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn-ghost { background: transparent; }
.btn-ghost:hover { background: rgba(255,255,255,0.04); }

.btn-danger {
  background: var(--danger-bg);
  border-color: #5a1f27;
  color: var(--danger-strong);
}
.btn-danger:hover {
  background: #3a161c;
  border-color: #7a2a35;
  color: #ff8a95;
}
.btn-danger.solid {
  background: var(--danger);
  border-color: var(--danger);
  color: #1b0608;
}
.btn-danger.solid:hover {
  background: var(--danger-strong);
  border-color: var(--danger-strong);
}

.icon {
  width: 16px; height: 16px;
  flex-shrink: 0;
}

/* Toast */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  background: #1c2230;
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 10px 16px;
  border-radius: 999px;
  font-size: 14px;
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: 10px;
  z-index: 60;
}
.toast .dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--danger-strong);
  box-shadow: 0 0 0 3px rgba(239, 79, 94, 0.18);
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 6, 10, 0.66);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 50;
  animation: fade 140ms ease-out;
}
.modal {
  width: min(440px, 100%);
  background: linear-gradient(180deg, #161a23 0%, #11141b 100%);
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  box-shadow: var(--shadow-lg);
  padding: 22px 22px 18px;
  animation: pop 160ms cubic-bezier(.2,.9,.3,1.2);
  outline: none;
}
.modal-head {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 14px;
}
.modal-icon {
  flex-shrink: 0;
  width: 40px; height: 40px;
  border-radius: 10px;
  background: var(--danger-bg);
  border: 1px solid #5a1f27;
  color: var(--danger-strong);
  display: grid; place-items: center;
}
.modal h2 {
  margin: 0 0 4px;
  font-size: 17px;
  letter-spacing: 0.1px;
}
.modal p { margin: 0; color: var(--text-muted); font-size: 14px; }
.modal-thumb {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px;
  margin: 14px 0 18px;
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
  border-radius: 10px;
}
.modal-thumb img {
  width: 56px; height: 56px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
}
.modal-thumb .meta { display: grid; gap: 2px; min-width: 0; }
.modal-thumb .name {
  font-size: 14px; font-weight: 600;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.modal-thumb .info { color: var(--text-dim); font-size: 12px; }
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop {
  from { opacity: 0; transform: translateY(8px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@media (prefers-reduced-motion: reduce) {
  .modal-backdrop, .modal { animation: none; }
}

/* Visually hidden but accessible to screen readers */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}
